/**
 * Safe alias failure. It contains no provider body, URL, credential, address, recipient, label,
 * adapter identifier, or stable resource identifier.
 */
public enum AliasError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Encrypted vault state is unavailable.
     */
    case VaultLocked
    /**
     * The requested encrypted connection metadata is unavailable.
     */
    case ConnectionMissing
    /**
     * The provider rejected the injected credential.
     */
    case AuthenticationRejected
    /**
     * The connection is not authorized for the requested resource or operation.
     */
    case PermissionDenied
    /**
     * The injected adapter does not expose a required capability.
     */
    case CapabilityUnsupported
    /**
     * Caller input is invalid.
     */
    case InvalidInput
    /**
     * The requested provider resource does not exist.
     */
    case NotFound
    /**
     * The provider account cannot create another resource.
     */
    case QuotaExhausted
    /**
     * The provider requested backoff.
     */
    case RateLimited(
        /**
         * Validated provider retry hint in seconds, when supplied.
         */retryAfterSeconds: UInt64?
    )
    /**
     * No provider connection is currently available.
     */
    case Offline
    /**
     * The provider operation timed out.
     */
    case Timeout
    /**
     * The provider service is temporarily unavailable.
     */
    case ServiceUnavailable
    /**
     * Adapter output violated the provider-neutral contract.
     */
    case InvalidResponse
    /**
     * A mutation may have committed and must be reconciled before replay.
     */
    case OutcomeUnknown
    /**
     * Concurrent facts require explicit resolution.
     */
    case SyncConflict
    /**
     * A local adapter, callback, or serialization security check failed.
     */
    case LocalSecurityFailure

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AliasError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAliasError: FfiConverterRustBuffer {
    typealias SwiftType = AliasError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AliasError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .VaultLocked
        case 2: return .ConnectionMissing
        case 3: return .AuthenticationRejected
        case 4: return .PermissionDenied
        case 5: return .CapabilityUnsupported
        case 6: return .InvalidInput
        case 7: return .NotFound
        case 8: return .QuotaExhausted
        case 9: return .RateLimited(
            retryAfterSeconds: try FfiConverterOptionUInt64.read(from: &buf)
            )
        case 10: return .Offline
        case 11: return .Timeout
        case 12: return .ServiceUnavailable
        case 13: return .InvalidResponse
        case 14: return .OutcomeUnknown
        case 15: return .SyncConflict
        case 16: return .LocalSecurityFailure

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AliasError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .VaultLocked:
            writeInt(&buf, Int32(1))
        
        
        case .ConnectionMissing:
            writeInt(&buf, Int32(2))
        
        
        case .AuthenticationRejected:
            writeInt(&buf, Int32(3))
        
        
        case .PermissionDenied:
            writeInt(&buf, Int32(4))
        
        
        case .CapabilityUnsupported:
            writeInt(&buf, Int32(5))
        
        
        case .InvalidInput:
            writeInt(&buf, Int32(6))
        
        
        case .NotFound:
            writeInt(&buf, Int32(7))
        
        
        case .QuotaExhausted:
            writeInt(&buf, Int32(8))
        
        
        case let .RateLimited(retryAfterSeconds):
            writeInt(&buf, Int32(9))
            FfiConverterOptionUInt64.write(retryAfterSeconds, into: &buf)
            
        
        case .Offline:
            writeInt(&buf, Int32(10))
        
        
        case .Timeout:
            writeInt(&buf, Int32(11))
        
        
        case .ServiceUnavailable:
