        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .matched(aliasId: try FfiConverterString.read(from: &buf), cipherId: try FfiConverterTypeCipherId.read(from: &buf)
        )
        
        case 2: return .staleBinding(aliasId: try FfiConverterString.read(from: &buf), cipherId: try FfiConverterTypeCipherId.read(from: &buf), referenceAddressStale: try FfiConverterBool.read(from: &buf), usernameStale: try FfiConverterBool.read(from: &buf)
        )
        
        case 3: return .duplicateBinding(aliasId: try FfiConverterString.read(from: &buf), cipherIds: try FfiConverterSequenceTypeCipherId.read(from: &buf)
        )
        
        case 4: return .missingAlias(aliasId: try FfiConverterString.read(from: &buf), cipherId: try FfiConverterTypeCipherId.read(from: &buf)
        )
        
        case 5: return .unboundAlias(aliasId: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .skippedCipher(cipherId: try FfiConverterOptionTypeCipherId.read(from: &buf), reason: try FfiConverterTypeAliasReconciliationSkipReason.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AliasReconciliationOutcome, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .matched(aliasId,cipherId):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(aliasId, into: &buf)
            FfiConverterTypeCipherId.write(cipherId, into: &buf)
            
        
