            FfiConverterString.write(aliasId, into: &buf)
            FfiConverterTypeCipherId.write(cipherId, into: &buf)
            FfiConverterBool.write(referenceAddressStale, into: &buf)
            FfiConverterBool.write(usernameStale, into: &buf)
            
        
