            writeInt(&buf, Int32(3))
            FfiConverterString.write(aliasId, into: &buf)
            FfiConverterSequenceTypeCipherId.write(cipherIds, into: &buf)
            
        
        case let .missingAlias(aliasId,cipherId):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(aliasId, into: &buf)
            FfiConverterTypeCipherId.write(cipherId, into: &buf)
            
        
        case let .unboundAlias(aliasId):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(aliasId, into: &buf)
            
        
        case let .skippedCipher(cipherId,reason):
            writeInt(&buf, Int32(6))
            FfiConverterOptionTypeCipherId.write(cipherId, into: &buf)
